let output = [];

let n8nItems = $('Preparar Nombre de Archivo (usa ID, no nombre)').all();
let githubNames = $('limpiar datos github').first().json.name || [];

// === MAPA DE WORKFLOWS DE N8N ===
let n8nMap = new Map();

// Formato actual: workflows/n8n-backup-g2SpEdjZuGsrMtWX
for (let item of n8nItems) {
  let full = item.json.name || '';
  let workflowId = item.json.id || '';

  let name = full.replace(/^workflows\/[^\/]+\//, '');
  name = name.replace(/^n8n-backup-/, '');

  n8nMap.set(workflowId, {
    source: 'n8n',
    full: full,
    name: name,
    id: workflowId
  });
}

// === MAPA DE ARCHIVOS EN GITHUB ===
let githubMap = new Map();

for (let filename of githubNames) {
  let withoutExt = filename.replace(/\.json$/, '');
  let parts = withoutExt.split('_');
  if (parts.length > 0) {
    let fullName = withoutExt;
    let name = fullName.replace(/^n8n-backup-/, '');

    githubMap.set(fullName, {
      source: 'github',
      full: filename,
      name: name,
      id: fullName
    });
  }
}

// === DETECTAR CAMBIOS DE NOMBRE ===
for (let [workflowId, n8n] of n8nMap) {
  let gh = githubMap.get(n8n.full);   // buscamos por nombre completo del archivo

  if (gh && n8n.name !== gh.name) {
    output.push({ json: { n8n, github: gh } });
  }
}

return output;

// Compara los workflows actuales de n8n contra los archivos que ya existen en GitHub,
// usando el ID real de cada workflow para encontrar coincidencias.

const workflows = items; // viene de "Captura de Workflows2"
const githubFiles = $('Get Índice1').all();

function extractId(fileName) {
  const withoutExt = fileName.replace(/\.json$/i, '');
  const match = withoutExt.match(/-([A-Za-z0-9]{15,25})$/);
  if (match) return match[1];
  return withoutExt;
}

const githubMap = new Map();
for (const file of githubFiles) {
  const fileName = file.json.name;
  const id = extractId(fileName);
  githubMap.set(id, { fileName, filePath: file.json.path });
}

const commitDate = $('Establecer campos2').first().json.commitDate;
const output = [];

for (const item of workflows) {
  const wf = item.json;
  const id = wf.id;
  const currentName = wf.name;

  const desiredFileName = `${currentName}-${id}.json`;
  const newFilePath = `workflows/${desiredFileName}`;
  const newFileContent = JSON.stringify(wf, null, 2);

  const existing = githubMap.get(id);

  if (!existing) {
    output.push({ json: {
      action: 'create', id, name: currentName,
      newFilePath, newFileContent,
      commitMessage: `Create workflow backup: ${currentName} (${commitDate})`
    }});
  } else if (existing.fileName !== desiredFileName) {
    output.push({ json: {
      action: 'rename', id, name: currentName,
      oldFilePath: existing.filePath,
      newFilePath, newFileContent,
      commitMessage: `Rename workflow backup: ${existing.fileName} -> ${desiredFileName} (${commitDate})`
    }});
  } else {
    output.push({ json: {
      action: 'update', id, name: currentName,
      newFilePath, newFileContent,
      commitMessage: `Update workflow backup: ${currentName} (${commitDate})`
    }});
  }
}

return output;

